    statements: dict[str, dict]
    sitelinks: dict[str, dict]
    _updated: datetime  # This is when we fetched the data, not when the entity was changed in Wikidata

    def get_description(self, language: str = 'en') -> str | None:
        """If a description isn't available in the requested language default to English"""
        return self.descriptions.get(language) or self.descriptions.get('en')

    def _get_wikipedia_link(self, language: str) -> tuple[str, str] | None:
        """Return a Wikipedia sitelink in the requested language, or English."""
        for link_language in (language, 'en'):
            sitelink = self.sitelinks.get(f'{link_language}wiki')
            if isinstance(sitelink, dict):
                url = sitelink.get('url')
                if isinstance(url, str) and url:
                    return url, link_language
        return None

    def _get_statement_values(self, property_id: str) -> list:
        """Return the content of valid statements for a Wikidata property."""
        statements = self.statements.get(property_id, [])
        if isinstance(statements, dict):
            statements = [statements]

        values = []
        for statement in statements:
            if not isinstance(statement, dict):
                continue
            value = statement.get('value')
            if isinstance(value, dict) and value.get('content') is not None:
                values.append(value['content'])
        return values

    def get_external_profiles(self, language: str = 'en') -> list[dict]:
        """Return links to this entity's Wikipedia, Wikidata, and other profiles."""
        profiles = []
        if wikipedia_link := self._get_wikipedia_link(language):
            profiles.append(
                {
                    'url': wikipedia_link[0],
                    'icon_url': '/static/images/identifier_icons/wikipedia.svg',
                    'label': 'Wikipedia',
                }
            )

        profiles.append(
            {
                'url': f'https://www.wikidata.org/wiki/{self.id}',
                'icon_url': '/static/images/identifier_icons/wikidata.svg',
                'label': 'Wikidata',
            }
        )

        for identifier in self._get_statement_values('P1960'):
            if isinstance(identifier, str) and identifier:
                profiles.append(
                    {
                        'url': f'https://scholar.google.com/citations?user={identifier}',
                        'icon_url': '/static/images/identifier_icons/google_scholar.svg',
                        'label': 'Google Scholar',
                    }
                )

        return profiles

